nav.script:



document.addEventListener('DOMContentLoaded', function () {
    // Alle <ul class="dropdown-menu"> finden
    document.querySelectorAll('#navbar .dropdown-menu').forEach(function(dropdownMenu){
        // Das Eltern-LI suchen
        let parentLi = dropdownMenu.parentElement;
        if (!parentLi) return;

        // Eltern-LI braucht .dropdown
        parentLi.classList.add('dropdown');

        // Das zugehörige A finden
        let toggleLink = parentLi.querySelector('a.nav-link');
        if (toggleLink) {
            // .dropdown-toggle hinzufügen
            toggleLink.classList.add('dropdown-toggle');
            // Für Bootstrap 5: data-bs-toggle setzen
            toggleLink.setAttribute('data-bs-toggle', 'dropdown');
            toggleLink.setAttribute('role', 'button');
            toggleLink.setAttribute('aria-expanded', 'false');
            // Optional: href auf "#" setzen, damit kein Seitenwechsel passiert (kannst du entfernen, wenn gewünscht)
            toggleLink.setAttribute('href', '#');
        }
    });
});

